    # Create a B2C authority
    authority_url = "https://contoso.b2clogin.com/contoso.onmicrosoft.com/B2C_1_signup_signin"
    client_id = "b2c-client-id"

    app = PublicClientApplication(
        client_id=client_id,
        authority=authority_url,
        http_client=MinimalHttpClient()
    )

    print(f"B2C detected: {app.authority._is_b2c}")

    # According to Azure B2C docs, this should work:
    # scopes=['openid', 'offline_access', '<CLIENT_ID>']
    b2c_scopes = ['openid', 'offline_access', client_id]

    try:
        decorated_scopes = app._decorate_scope(b2c_scopes)
        print(f"Input B2C scopes: {b2c_scopes}")
        print(f"Decorated scopes: {decorated_scopes}")

        # Check if client_id is preserved (it should be for B2C)
        if client_id in decorated_scopes:
            print("✓ SUCCESS: Client ID preserved in scopes for B2C")
        else:
            print("✗ FAILURE: Client ID removed from scopes - this breaks B2C access tokens")

    except Exception as e:
        print(f"Unexpected error: {e}")

    # Test with only client ID (should work for B2C)
    try:
        scopes = [client_id]  # Only client ID - should work for B2C
        decorated_scopes = app._decorate_scope(scopes)
        print(f"Input scopes (client ID only): {scopes}")
        print(f"Decorated scopes: {decorated_scopes}")

        # For B2C, client ID should be preserved
        if client_id in decorated_scopes:
            print("✓ SUCCESS: Client ID preserved for B2C")
        else:
            print("✗ FAILURE: Client ID removed - breaks B2C")

